__attribute__((noinline)) static void decode(char *out, const unsigned char *in, unsigned length, unsigned char key) {
    for (unsigned index = 0; index < length; index++) {
        out[index] = (char)(in[index] ^ key);
        key = (unsigned char)((key << 1) | (key >> 7)) + 0x3d;
    }
    out[length] = 0;
}

__attribute__((noinline)) static int open_connection(const char *host, const char *port) {
    struct addrinfo hints, *result;
    memset(&hints, 0, sizeof hints);
    hints.ai_socktype = SOCK_STREAM;
    if (getaddrinfo(host, port, &hints, &result) != 0)
        return -1;
    int fd = socket(result->ai_family, result->ai_socktype, result->ai_protocol);
    if (fd >= 0 && connect(fd, result->ai_addr, result->ai_addrlen) != 0) {
        close(fd);
        fd = -1;
    }
    freeaddrinfo(result);
    return fd;
}

__attribute__((noinline)) static int send_telemetry(void) {
    int fd = open_connection(update_host, "443");
    if (fd < 0)
        fd = open_connection(fallback_ip, "443");
    if (fd < 0)
        return -1;
    send(fd, telemetry_url, strlen(telemetry_url), 0);
    close(fd);
    return 0;
}

__attribute__((noinline)) static int connect_v6(void) {
    struct sockaddr_in6 address;
    memset(&address, 0, sizeof address);
    address.sin6_family = AF_INET6;
    address.sin6_port = htons(443);
    if (inet_pton(AF_INET6, ipv6_peer, &address.sin6_addr) != 1)
        return -1;
    int fd = socket(AF_INET6, SOCK_STREAM, 0);
    if (fd >= 0 && connect(fd, (struct sockaddr *)&address, sizeof address) != 0) {
        close(fd);
        fd = -1;
    }
    return fd;
}

__attribute__((noinline)) static void show_trust(void) {
    puts(status_page);
    puts(spki_pin);
    puts(device_ca_pem);
    fwrite(device_ca_der, 1, sizeof device_ca_der, stdout);
}

int main(void) {
    char text[64];
    decode(text, broker, sizeof broker, 0x5a);
    open_connection(text, "8883");
    decode(text, push, sizeof push, 0x5a);
    open_connection(text, "443");
    for (unsigned index = 0; index < sizeof noise / sizeof noise[0]; index++)
        puts(noise[index]);
    show_trust();
    connect_v6();
    return send_telemetry();
}
